<template>
  <div class="page">
    <div class="category-manage__table-wrap">
      <div class="panel">
        <div class="panel__header">
          <div class="panel__title">
            <h3>商品分类</h3>
          </div>
          <div class="panel__actions">
            <el-button type="primary" size="small" @click="openAddDialog">新增分类</el-button>
          </div>
        </div>
        <div class="panel__table-wrap">
          <el-table ref="tableRef" :data="pagedData" style="width: 100%" :header-cell-style="{ textAlign: 'left' }" :cell-style="{ textAlign: 'left' }">
            <el-table-column prop="id" label="ID" min-width="70" />
            <el-table-column prop="name" label="分类名称" min-width="180" />
            <el-table-column prop="sortOrder" label="排序" min-width="90" />
            <el-table-column label="状态" min-width="90">
              <template #default="scope">
                <el-tag :type="scope.row.status === 1 ? 'success' : 'danger'" disable-transitions>
                  {{ scope.row.status === 1 ? '启用' : '停用' }}
                </el-tag>
              </template>
            </el-table-column>
            <el-table-column prop="createTime" label="创建时间" min-width="170" />
            <el-table-column label="操作" min-width="160">
              <template #default="scope">
                <el-button size="small" type="primary" link @click="openEditDialog(scope.row)">编辑</el-button>
                <el-button size="small" type="danger" link @click="handleDelete(scope.row)">删除</el-button>
              </template>
            </el-table-column>
          </el-table>
        </div>
      </div>
      <div class="category-manage__pagination-wrap">
        <div class="totalnum">
          <h3>分类统计</h3>
          <p>当前共 {{ tableData.length }} 个分类</p>
        </div>
        <div class="example-pagination-block">
          <el-pagination
            layout="prev, pager, next"
            :total="tableData.length"
            :page-size="pageSize"
            :current-page="currentPage"
            @current-change="currentPage = $event"
          />
        </div>
      </div>

      <el-dialog v-model="dialogVisible" :title="dialogTitle" width="480px">
        <el-form ref="addFormRef" :model="addForm" :rules="addFormRules" label-width="90px">
          <el-form-item label="分类名称" prop="name">
            <el-input v-model="addForm.name" placeholder="请输入分类名称" />
          </el-form-item>
          <el-form-item label="排序" prop="sortOrder">
            <el-input-number v-model="addForm.sortOrder" :min="0" style="width: 100%" />
          </el-form-item>
          <el-form-item label="状态" prop="status">
            <el-select v-model="addForm.status" style="width: 100%">
              <el-option label="启用" :value="1" />
              <el-option label="停用" :value="0" />
            </el-select>
          </el-form-item>
        </el-form>
        <template #footer>
          <el-button @click="dialogVisible = false">取消</el-button>
          <el-button type="primary" @click="handleSubmit">确 定</el-button>
        </template>
      </el-dialog>
    </div>
  </div>
</template>

<script setup>
import { ref, computed, reactive, onMounted, getCurrentInstance   } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
const {proxy} = getCurrentInstance()

const currentPage = ref(1)
const pageSize = ref(6)

// 新增/编辑分类(categories 表)
const dialogVisible = ref(false)
const dialogMode = ref('add') // add | edit
const editIndex = ref(-1)
const dialogTitle = computed(() => (dialogMode.value === 'add' ? '新增分类' : '编辑分类'))
const addFormRef = ref()
const addForm = reactive({
  name: '',
  sortOrder: 0,
  status: 1,
})
//表单验证规则
const addFormRules = {
  name: [{ required: true, message: '请输入分类名称', trigger: 'blur' }],
}
//新增弹窗
const openAddDialog = () => {
  dialogMode.value = 'add'
  addForm.name = ''
  addForm.sortOrder = 0
  addForm.status = 1
  dialogVisible.value = true
}
//编辑
const openEditDialog = (row) => {
  dialogMode.value = 'edit'
  editIndex.value = tableData.value.indexOf(row)
  addForm.name = row.name
  addForm.sortOrder = row.sortOrder
  addForm.status = row.status
  dialogVisible.value = true
}
//提交
const handleSubmit = () => {
  addFormRef.value.validate((valid) => {
    if (!valid) return
    if (dialogMode.value === 'add') {
      const newCategory = {
        name: addForm.name,
        sortOrder: addForm.sortOrder,
        status: addForm.status
      }
      proxy.$request.post('/api/categories', newCategory).then(res=>{
        if(res.code === 1){
          categoryList()
        } else {
          console.error('新增分类接口返回结构异常：', res)
        }
      })
      currentPage.value = 1
      ElMessage.success(`分类「${addForm.name}」已新增`)
    } else {
      const row = tableData.value[editIndex.value]
      const updatedCategory = {
        name: addForm.name,
        sortOrder: addForm.sortOrder,
        status: addForm.status,
      }
      proxy.$request.put(`/api/categories/${row.id}`, updatedCategory).then(res=>{
        if(res.code === 1){
          //更新成功后调用分类列表接口刷新数据
          categoryList()
        } else {
          console.error('更新分类接口返回结构异常：', res)
        }
      })
      ElMessage.success(`分类「${addForm.name}」已更新`)
    }
    dialogVisible.value = false
  })
}

// 删除分类
const handleDelete = (row) => {
  ElMessageBox.confirm(`确定删除分类「${row.name}」吗？`, '提示', { type: 'warning' })
    .then(() => {
      proxy.$request.delete(`/api/categories/${row.id}`).then(res => {
        if (res.code === 1) {
          ElMessage.success(`分类「${row.name}」已删除`)
          categoryList()
        } else {
          console.error('删除分类接口返回结构异常：', res)
        }
      })
    })
    .catch(() => {}) // 取消删除
}
//分页
const pagedData = computed(() => {
  const start = (currentPage.value - 1) * pageSize.value
  return tableData.value.slice(start, start + pageSize.value)
})

// 分类数据(categories 表结构)
const tableData = ref([]) 
// 初始化时从接口拉取分类列表
onMounted(()=>{
  categoryList()
})
// 从分类接口拉取列表
const categoryList = ()=>{
  proxy.$request.get('/api/categories').then(res=>{
    if(res.code === 1){
        tableData.value = res.data
      } else {
        console.error('分类接口返回结构异常：', res)
      }
  })
}
</script>

<style scoped>
.category-manage__table-wrap {
  background-color: #ffffff;
  margin: 12px;
  border-radius: 8px;
  min-width: 0;
  overflow-x: auto;
}
.panel {
  box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);
  background-color: #ffffff;
  border-radius: 8px;
  .panel__header {
    display: flex;
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    padding: 12px;
  }
}
.category-manage__pagination-wrap {
  display: flex;
  flex-direction: row;
  align-items: center;
  justify-content: flex-start;
  padding: 12px;
  .example-pagination-block {
    flex: 1;
  }
  .totalnum {
    flex: 4;
    display: flex;
    flex-direction: column;
    align-items: flex-start;
    justify-content: flex-start;
    padding: 12px;
    h3 {
      margin: 0;
      font-size: 16px;
    }
